const $=s=>document.querySelector(s);
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',targets:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',inbox:'<path d="M4 4h16v15H4zM4 13h5l2 3h2l2-3h5"/>',plan:'<path d="M8 4h12M8 12h12M8 20h12M3 4h1M3 12h1M3 20h1"/>',meetings:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M8 15h3"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>',pause:'<path d="M9 5v14M15 5v14"/>',play:'<path d="m7 4 14 8-14 8z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={paused:false,resolved:[],excluded:[],name:'Queensland industrial services',budget:450,cap:15,anonymous:true,followups:true,calendar:true,description:'Acquire an established industrial maintenance or engineering services business in Queensland. Target $1–3m EBITDA, recurring B2B customers, and an owner open to succession. Prefer an experienced management team.'};
let saved;try{saved=JSON.parse(localStorage.getItem('acquire-concept-v1'))}catch{}let state={...initial,...saved},view='overview',filter='All targets',query='',wizardStep=0;
const companies=[{id:'northline',name:'Northline Engineering',initials:'NE',location:'Brisbane, QLD',sector:'Industrial maintenance',fit:94,revenue:'$8–12m',ebitda:'Not verified',stage:'Meeting booked',owner:'David Wilson',role:'Founder & Managing Director',staff:'38–45',detail:'Maintenance and reliability services for industrial facilities across South East Queensland.',evidence:'Company services page · captured 14 Oct',next:'Introductory meeting · Fri 16 Oct, 10:00 am AEST'}, {id:'coastal',name:'Coastal Plant Services',initials:'CP',location:'Gold Coast, QLD',sector:'Plant maintenance',fit:91,revenue:'$6–10m',ebitda:'Not verified',stage:'Needs attention',owner:'Sarah Mitchell',role:'Managing Director',staff:'25–35',detail:'Preventative maintenance and shutdown support for manufacturing and processing facilities.',evidence:'Company website and directory record · 14 Oct',next:'Buyer identity question awaiting your decision'}, {id:'precision',name:'Precision Fieldworks',initials:'PF',location:'Toowoomba, QLD',sector:'Engineering services',fit:88,revenue:'$5–8m',ebitda:'$1.2m estimate',stage:'Meeting booked',owner:'James Carter',role:'Owner & Director',staff:'20–30',detail:'Field servicing and engineering support for agricultural and industrial equipment.',evidence:'Company capability statement · 13 Oct',next:'Owner requested available times for next week'}, {id:'summit',name:'Summit Mechanical',initials:'SM',location:'Sunshine Coast, QLD',sector:'Mechanical maintenance',fit:86,revenue:'$7–11m',ebitda:'Not verified',stage:'In conversation',owner:'Michael Reed',role:'Founder',staff:'30–40',detail:'Mechanical maintenance contracts and equipment repair for commercial and industrial customers.',evidence:'Company website · 14 Oct',next:'Follow-up scheduled · Mon 19 Oct'}, {id:'redgum',name:'Redgum Industrial',initials:'RI',location:'Ipswich, QLD',sector:'Industrial services',fit:83,revenue:'$4–7m',ebitda:'Not verified',stage:'Researching',owner:'Alex Morgan',role:'Director · ownership unverified',staff:'15–25',detail:'Industrial fabrication and maintenance with a growing regional customer base.',evidence:'Public business directory · 14 Oct',next:'Verify ownership and recurring contract mix'}, {id:'atlas',name:'Atlas Reliability',initials:'AR',location:'Brisbane, QLD',sector:'Reliability engineering',fit:81,revenue:'$3–6m',ebitda:'Not verified',stage:'Needs attention',owner:'Emma Brooks',role:'Managing Director',staff:'12–20',detail:'Condition monitoring and reliability engineering for manufacturers.',evidence:'Company services and team pages · 14 Oct',next:'Decide whether to approach with financial fit unknown'}];
const exceptions=[{id:'identity',company:'Coastal Plant Services',title:'How much buyer detail can I share?',summary:'Sarah is open to a conversation and has asked who the buyer is. Your plan currently allows an anonymous introduction only.',recommendation:'Share the approved buyer introduction for this conversation.',label:'Buyer disclosure',button:'Review response'}, {id:'financial',company:'Atlas Reliability',title:'A strong fit, with one important unknown',summary:'Sector, location and service model match. Public sources do not establish EBITDA. I can make an exploratory approach without claiming financial fit.',recommendation:'Approach with an introductory question; keep financial fit unverified.',label:'Qualification decision',button:'Review target'}];
const activities=[['Meeting booked','David at Northline Engineering confirmed an introductory call.','Today · 9:42 am'],['Reply received','Sarah at Coastal asked for more information about the buyer.','Today · 9:18 am'],['Research completed','6 additional companies assessed. 4 match the service scope.','Today · 8:56 am'],['Outreach submitted','Personalised introductions submitted for 5 eligible contacts.','Today · 8:30 am'],['Follow-up deferred','Precision Fieldworks is in conversation. Cold follow-ups remain stopped.','Yesterday · 4:16 pm'],['Mandate activated','Operating plan v3 approved. Email-only outreach enabled in this demo.','12 Oct · 10:00 am']];
function save(){try{localStorage.setItem('acquire-concept-v1',JSON.stringify(state))}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function pending(){return exceptions.filter(e=>!state.resolved.includes(e.id))}
function nav(v){view=v;query='';filter='All targets';render();window.scrollTo(0,0)}
function btn(t,a,cl=''){return `<button class="btn ${cl}" ${a}>${t}</button>`}
function header(title,sub,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p class="subtitle">${sub}</p></div><div class="buttons">${actions}</div></div>`}
function status(){return `<span class="status ${state.paused?'paused':''}"><i class="dot"></i>${state.paused?'Mandate paused':'Agent active'}</span>`}
function render(){const n=pending().length;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">a</span>acquire<span style="font-size:10px;color:var(--muted);align-self:flex-end;margin-bottom:4px"> / agent</span></div><div class="workspace">ACQUISITION WORKSPACE<strong>Queensland buy-side <span style="float:right">⌄</span></strong></div><div class="eyebrow nav-label">Your mandate</div><nav class="nav" aria-label="Main navigation">${[['overview','Overview'],['inbox','Needs attention'],['targets','Targets'],['meetings','Meetings'],['plan','Operating plan'],['activity','Activity']].map(([v,t])=>`<button data-nav="${v}" class="${view===v?'active':''}">${icon(v)}${t}${v==='inbox'&&n?`<span class="count">${n}</span>`:''}</button>`).join('')}</nav><div style="padding:24px 12px">${btn(icon('plus')+' New mandate','data-action="new"','small')}</div><div class="sidebar-bottom"><div class="demo-note"><span class="pill gray">INTERACTIVE CONCEPT</span><p style="margin-top:9px">Fictional companies. Nothing is sent.<br>Changes stay in this browser.</p><button class="text-link" style="margin-top:9px" data-action="reset">Reset demo ↻</button></div><div class="user"><span class="avatar">CH</span><div style="font-size:12px">Callum Holt<div class="muted" style="font-size:10px;margin-top:4px">Workspace owner</div></div></div></div></aside><main class="main"><header class="topbar"><span>Mandates <span style="margin:0 10px;color:#52604e">/</span> <strong>${esc(state.name)}</strong></span><div class="top-actions"><span class="tiny">Saved locally</span><span class="tag">PROTOTYPE</span></div></header><div class="content view-enter"><div class="spread"><span class="eyebrow">Mandate 001 <span style="color:#54614e;margin:0 8px">/</span> Acquisition origination</span>${status()}</div>${({overview:overview,inbox:inbox,targets:targets,meetings:meetings,plan:plan,activity:activity}[view]||overview)()}<div class="footer-note">${icon('shield')} Concept preview · All records and activity are illustrative · No live connections</div></div></main></div>`;bind()}
function overview(){return header(state.name,'Your mandate is working. Here’s where things stand.',btn(icon(state.paused?'play':'pause')+(state.paused?'Resume mandate':'Pause mandate'),'data-action="pause"')+btn('View operating plan '+icon('arrow'),'data-nav="plan"'))+`<div class="mission-strip"><div class="agent-symbol">✳</div><div><p>${state.paused?'All new research and outreach are paused.':"I’m building conversations with the right business owners."}</p><small>${state.paused?'Your progress is saved. Resume when you’re ready.':`Next: ${pending().length?'resolve '+pending().length+' decisions, then ':''}continue researching 8 companies. Follow-ups resume Monday.`}</small></div>${status()}</div><div class="stats">${[['Meetings booked','3','2 coming up this week','meetings'],['Owners in conversation','8','+3 since Monday','targets'],['Qualified for approach','32','Evidence-backed shortlist','targets'],['Companies discovered','124','Across 4 source types','targets']].map(([t,n,f,v])=>`<button class="stat" data-nav="${v}"><div class="spread stat-label">${t}<span class="muted">↗</span></div><div class="stat-number">${n}</div><div class="stat-foot ${f.startsWith('+')?'positive':''}">${f}</div></button>`).join('')}</div><div class="columns"><div><section class="panel"><div class="panel-head"><h2>Needs your attention <span class="pill amber" style="margin-left:7px">${pending().length}</span></h2><button class="text-link" data-nav="inbox">View inbox ${icon('arrow')}</button></div>${pending().length?pending().map(e=>`<div class="attention-item"><div class="attention-icon">↗</div><div class="attention-copy"><div class="small-meta">${e.company} <span style="margin:0 5px">·</span> ${e.label}</div><h3>${e.title}</h3><p>${e.summary}</p>${btn(e.button+' '+icon('arrow'),`data-exception="${e.id}"`,'small')}</div></div>`).join(''):'<div class="empty"><b>✓ You’re all caught up</b>Your agent can continue within the operating plan.</div>'}</section><section class="panel"><div class="panel-head"><h2>Coming up</h2><button class="text-link" data-nav="meetings">All meetings ${icon('arrow')}</button></div>${meetingRows()}</section><section class="panel"><div class="panel-head"><h2>Recent activity</h2><button class="text-link" data-nav="activity">View all ${icon('arrow')}</button></div><div class="panel-body" style="padding-top:4px">${activityRows(3)}</div></section></div><div><section class="panel"><div class="panel-head"><h2>Your pipeline</h2><span class="tiny muted">This mandate</span></div><div class="panel-body"><p class="helper">From market coverage to owner conversations.</p><div class="pipeline"><span style="flex:124"></span><span style="flex:68"></span><span style="flex:32"></span><span style="flex:18"></span></div>${[['Discovered','124'],['Researched','68'],['Qualified for approach','32'],['Contacted','18'],['In conversation','8'],['Meetings booked','3']].map(([t,n])=>`<div class="funnel-row"><span>${t}</span><b>${n}</b></div>`).join('')}<div class="rule"></div><button class="text-link" data-nav="targets">Explore targets ${icon('arrow')}</button></div></section><section class="panel"><div class="panel-head"><h2>Operating envelope</h2>${icon('shield')}</div><div class="panel-body"><div class="spread tiny"><span class="muted">Research spend</span><span>$126 <span class="muted">/ $${state.budget}</span></span></div><div class="meter"><span style="width:${Math.min(100,126/state.budget*100)}%"></span></div><div class="tiny muted">Within your monthly limit</div><div class="rule"></div><div class="spread tiny"><span class="muted">Outreach today</span><span>5 / ${state.cap} contacts</span></div><div class="meter"><span style="width:${Math.min(100,5/state.cap*100)}%"></span></div><div class="rule"></div><div class="spread tiny"><span class="muted">Channels</span><span>Email only</span></div><div class="spread tiny" style="margin-top:14px"><span class="muted">Buyer identity</span><span>${state.anonymous?'Anonymous first':'Approved profile'}</span></div><button class="text-link" style="margin-top:23px" data-nav="plan">Review authority ${icon('arrow')}</button></div></section></div></div>`}
function meetingRows(){return [['16','OCT','Northline Engineering','David Wilson · Fri, 10:00–10:30 am AEST','northline'],['20','OCT','Precision Fieldworks','James Carter · Tue, 2:00–2:30 pm AEST','precision']].map(([d,m,n,t,id])=>`<div class="meeting-card"><div class="datebox">${m}<b>${d}</b></div><div><h3>${n}</h3><p>${t}</p></div><button class="text-link" data-meeting="${id}">Briefing ${icon('arrow')}</button></div>`).join('')}
function activityRows(n=activities.length){return activities.slice(0,n).map(([t,d,time])=>`<div class="activity-item"><div class="activity-dot"></div><div><p><strong style="font-weight:500">${esc(t)}</strong> <span class="muted">— ${esc(d)}</span></p><small>${time}</small></div></div>`).join('')}
function inbox(){return header('Needs your attention','Decisions that need your judgement. Everything else keeps moving.')+`<div class="notice">${icon('shield')} Decisions apply only to the selected target unless you explicitly update the operating plan.</div>${pending().length?pending().map(e=>`<section class="panel"><div class="panel-head"><span class="pill amber">${e.label}</span><span class="tiny muted">Today · ${e.id==='identity'?'9:18':'8:52'} am</span></div><div class="panel-body"><div class="small-meta">${e.company}</div><h2>${e.title}</h2><p class="subtitle" style="max-width:750px">${e.summary}</p><div class="callout"><span class="eyebrow">Recommended next action</span><p class="tiny" style="margin-top:9px">${e.recommendation}</p></div>${btn('Review and decide '+icon('arrow'),`data-exception="${e.id}"`,'primary')}</div></section>`).join(''):'<section class="panel"><div class="empty"><b>✓ No decisions waiting</b>Your agent is continuing within the agreed plan.<br><button class="text-link" data-nav="overview">Back to overview →</button></div></section>'}<p class="helper">${state.resolved.length} resolved in this demo session. Reply holds remain in place while a conversation is handled.</p>`}
function targets(){return header('Targets','A living shortlist, with the evidence and next action behind every company.')+`<div class="toolbar"><div class="filters">${['All targets','Needs attention','In conversation','Meeting booked'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><label class="search">${icon('search')}<input id="target-search" aria-label="Search targets" placeholder="Search companies…" value="${esc(query)}"></label></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Company</th><th>Fit</th><th>Revenue</th><th>Status</th><th></th></tr></thead><tbody id="target-rows">${targetRows()}</tbody></table></div></section><p class="helper">Showing 6 illustrative companies from a fictional 124-company universe. Fit describes supported criteria; it does not verify EBITDA or willingness to sell.</p>`}
function currentStage(c){return state.excluded.includes(c.id)?'Excluded':c.id==='coastal'&&state.resolved.includes('identity')?'In conversation':c.id==='atlas'&&state.resolved.includes('financial')?'Outreach active':c.stage}
function targetRows(){const list=companies.filter(c=>(filter==='All targets'||currentStage(c)===filter)&&c.name.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(c=>`<tr data-company="${c.id}" tabindex="0" role="button" aria-label="Open ${c.name}"><td><div class="company-cell"><span class="company-logo">${c.initials}</span><div>${c.name}<small>${c.location} · ${c.sector}</small></div></div></td><td><span class="score">${c.fit}</span><small>Supported fit</small></td><td>${c.revenue}<small>Indicative band</small></td><td><span class="pill ${['Excluded','Researching'].includes(currentStage(c))?'gray':currentStage(c)==='Needs attention'?'amber':''}">${currentStage(c)}</span></td><td>↗</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty">No companies match this view.</div></td></tr>'}
function meetings(){return header('Meetings','Owner conversations, prepared before you join.')+`<div class="notice">All times shown in Brisbane time (AEST, UTC+10). Bookings and attendees are fictional.</div><section class="panel"><div class="panel-head"><h2>Upcoming · 2</h2><span class="pill">Confirmed</span></div>${meetingRows()}</section><section class="panel"><div class="panel-head"><h2>Completed · 1</h2></div><div class="meeting-card"><div class="datebox">OCT<b>13</b></div><div><h3>Harbour Technical Services</h3><p>Oliver Hayes · Introductory call completed</p></div><button class="text-link" data-action="completed">View notes ${icon('arrow')}</button></div></section><div class="panel"><div class="panel-body"><h3>What counts as a booked meeting?</h3><p class="subtitle">An agreed time, named attendees and a confirmed calendar record. An interested reply alone stays in the conversation stage.</p></div></div>`}
function plan(){return header('Operating plan','The brief, boundaries and authority your agent works within.',btn('Save operating plan '+icon('check'),'data-action="save-plan"','primary'))+`<div class="notice">Plan v3 · Demo changes are saved to this browser only. No outreach or calendar actions will run.</div><div class="grid2"><div><section class="panel"><div class="panel-head"><h2>Acquisition brief</h2><span class="pill gray">Editable</span></div><div class="panel-body"><div class="field"><label for="plan-name">Mandate name</label><input id="plan-name" value="${esc(state.name)}"></div><div class="field"><label for="plan-description">What are we looking for?</label><textarea id="plan-description" style="min-height:170px">${esc(state.description)}</textarea></div><div class="fact-grid"><div class="fact"><small>Geography</small><b>Queensland, Australia</b></div><div class="fact"><small>Earnings preference</small><b>$1–3m EBITDA</b></div></div><p class="helper">Missing financial information stays unknown. Estimates do not become verified qualification evidence.</p></div></section><section class="panel"><div class="panel-head"><h2>Resources and limits</h2></div><div class="panel-body"><div class="field"><label for="plan-budget">Monthly research budget (AUD)</label><input id="plan-budget" type="number" min="126" max="10000" value="${state.budget}"></div><div class="field"><label for="plan-cap">Maximum new contacts per day</label><input id="plan-cap" type="number" min="5" max="50" value="${state.cap}"></div><p class="helper">Account limits, reply coverage and suppression checks still apply before every send.</p></div></section></div><div><section class="panel"><div class="panel-head"><h2>Delegated authority</h2>${icon('shield')}</div><div class="panel-body">${[['anonymous','Anonymous first introduction','Keep buyer identity private until explicitly permitted.'],['followups','Follow up within the plan','Up to two follow-ups; stop on any genuine reply.'],['calendar','Arrange introductory meetings','Offer 30-minute calls within the approved calendar.']].map(([k,t,d])=>`<div class="setting"><div><p>${t}</p><small>${d}</small></div><button class="toggle ${state[k]?'on':''}" data-toggle="${k}" role="switch" aria-checked="${state[k]}" aria-label="${t}"><i></i></button></div>`).join('')}<div class="rule"></div><div class="field"><label>Permitted channel</label><div class="pill">Email · approved sender</div></div><div class="field"><label>Meeting availability</label><p class="tiny">Tuesday–Friday · 10:00 am–4:00 pm AEST<br>30 minutes · 15-minute buffer</p></div><p class="helper">Pricing, transaction terms, confidential documents and commitments always come back to you.</p></div></section><section class="panel"><div class="panel-head"><h2>Approved introduction</h2></div><div class="panel-body"><div class="brief-box">We represent a buyer interested in established Queensland industrial services businesses. They value continuity for staff and customers and would welcome an introductory conversation about your longer-term plans.</div><p class="helper" style="margin-top:14px">Private financial criteria and capital details are excluded from outreach.</p></div></section></div></div>`}
function activity(){return header('Activity','A readable record of actions, decisions and waiting states.')+`<section class="panel"><div class="panel-head"><h2>Mandate timeline</h2><span class="pill gray">Illustrative history</span></div><div class="panel-body" style="padding-top:4px">${activityRows()}</div></section><div class="notice">Every execution would retain its mandate version, evidence, authority and outcome. This prototype demonstrates the presentation using fictional events.</div>`}
function drawer(title,kicker,html){$('#overlay').innerHTML=`<div class="backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-head"><div><span class="eyebrow">${kicker}</span><h2 id="drawer-title">${title}</h2></div><button class="close" data-close aria-label="Close dialog">×</button></header><div class="drawer-body">${html}</div></section></div>`;document.body.style.overflow='hidden';bindOverlay();$('.close').focus()}
function close(){ $('#overlay').innerHTML='';document.body.style.overflow='';document.querySelector('.nav .active')?.focus()}
function openCompany(id){const c=companies.find(c=>c.id===id);drawer(c.name,'Target case file',`<div class="spread"><span class="pill">${currentStage(c)}</span><span class="score">${c.fit}<span class="tiny muted"> / 100 supported fit</span></span></div><p style="margin-top:20px">${c.detail}</p><div class="fact-grid">${[['Location',c.location],['Revenue',c.revenue+' · indicative'],['EBITDA',c.ebitda],['Employees',c.staff+' · indicative']].map(([k,v])=>`<div class="fact"><small>${k}</small><b>${v}</b></div>`).join('')}</div><h3>Why this company?</h3><p>Relevant industrial service offering, Queensland operations, and an established team. Recurring customer relationships appear plausible but require confirmation.</p><div class="source">Illustrative evidence: ${c.evidence}</div><div class="callout amber"><span class="eyebrow">Still to establish</span><p style="margin-top:9px">Verified earnings, owner succession intentions, customer concentration and management independence.</p></div><h3>Decision maker</h3><p>${c.owner}<br>${c.role}</p><h3>Next action</h3><p>${c.next}</p><h3>Case history</h3><div class="timeline"><p><small>12 OCT · DISCOVERED</small>Found through industry directory coverage.</p><p><small>13 OCT · RESEARCHED</small>Service offering and geography supported by company sources.</p><p><small>14 OCT · ASSESSED</small>Fit recorded with financial unknowns retained.</p></div><div class="drawer-actions">${btn(state.excluded.includes(id)?'Restore target':'Exclude from mandate',`data-exclude="${id}"`)}${c.stage==='Meeting booked'?btn('Open meeting briefing',`data-meeting="${id}"`,'primary'):btn('View conversation',`data-conversation="${id}"`,'primary')}</div>`)}
function openException(id){const e=exceptions.find(e=>e.id===id);const identity=id==='identity';drawer(e.title,e.company,`<span class="pill amber">${e.label}</span><p style="margin-top:19px">${e.summary}</p>${identity?`<h3>Latest message</h3><div class="message inbound"><small>Sarah Mitchell · Today, 9:18 am</small><p>Thanks for reaching out. I’d be open to a conversation. Could you tell me a little more about who you represent first?</p></div><h3>Proposed response</h3><div class="field"><label for="reply-text">You can edit this draft</label><textarea id="reply-text" style="min-height:155px">Thanks Sarah. We represent an Australian buyer looking to acquire and operate an established industrial services business for the long term. Continuity for staff and customers is important to them. Would a short introductory call next week suit?</textarea></div>`:`<h3>What the evidence supports</h3><div class="fact-grid"><div class="fact"><small>Sector and location</small><b>Supported</b></div><div class="fact"><small>EBITDA</small><b>Unknown</b></div></div><p>An exploratory introduction can ask about the owner’s plans without claiming the company meets your financial preference.</p>`}<div class="callout"><span class="eyebrow">Recommended action</span><p style="margin-top:9px">${e.recommendation}</p></div><label class="check-row"><input type="checkbox" id="exception-authority">${identity?'I approve this disclosure for this conversation only.':'I approve an exploratory approach with financial fit unverified.'}</label><div class="drawer-actions">${btn(identity?'Approve response (demo)':'Approve approach (demo)',`data-resolve="${id}"`,'primary')}${btn('Keep for review','data-close')}</div><p class="helper" style="margin-top:18px">Simulation only. No message is sent. Cold follow-ups remain stopped after a reply.</p>`)}
function openMeeting(id){const c=companies.find(c=>c.id===id);drawer('Your meeting briefing',c.name,`<span class="pill">Confirmed · illustrative booking</span><h3 style="font-size:21px;margin-top:25px">${id==='northline'?'Friday 16 October':'Tuesday 20 October'}</h3><p>${id==='northline'?'10:00–10:30 am':'2:00–2:30 pm'} AEST · 30-minute introductory call</p><div class="fact-grid"><div class="fact"><small>Business owner</small><b>${c.owner}</b></div><div class="fact"><small>Buyer representative</small><b>Callum Holt</b></div></div><h3>The business</h3><p>${c.detail}</p><h3>What we know</h3><p>Queensland operations and service scope match. The company appears established, with an experienced team. Earnings and deal readiness remain unverified.</p><h3>Conversation so far</h3><div class="message inbound"><small>${c.owner} · illustrative reply</small><p>I’m not actively running a sale process, but I’d be happy to understand a little more about the buyer and what they have in mind.</p></div><h3>Suggested questions</h3><p>1. What would you like the next chapter of the business to look like?<br>2. How much of the work comes from recurring relationships?<br>3. Who runs operations when you’re away?<br>4. What would make an acquisition conversation worthwhile?</p><div class="callout amber"><p>Keep this exploratory. No price, financing or transaction commitments have been made.</p></div><div class="drawer-actions">${btn('View target case',`data-company="${id}"`)}${btn('Copy briefing',`data-copy="${id}"`,'primary')}</div>`)}
function openConversation(id){const c=companies.find(c=>c.id===id);drawer('Conversation',c.name,`<span class="pill gray">${c.stage}</span><div class="message"><small>Acquire · approved buyer introduction</small><p>We’re speaking with owners of established industrial services businesses in Queensland. Your work caught our attention. Would you be open to an introductory conversation about your longer-term plans?</p></div>${['precision','coastal'].includes(id)?`<div class="message inbound"><small>${c.owner} · illustrative incoming reply</small><p>${id==='coastal'?'Could you tell me who you represent?':'Happy to have a chat. What times do you have next week?'}</p></div><div class="callout"><p>Cold follow-ups stopped. ${id==='coastal'?'Buyer disclosure needs your decision.':'Next action: propose available times within the approved calendar.'}</p></div>`:'<div class="callout"><p>No confirmed reply is shown in this example. Any follow-up must pass current policy and reply checks.</p></div>'}<div class="drawer-actions">${btn('Back to target',`data-company="${id}"`)}${id==='coastal'?btn('Review decision','data-exception="identity"','primary'):''}</div>`)}
function wizard(){if(wizardStep===0)drawer('What are you looking to acquire?','New mandate · 1 of 2',`<div class="progress-track"><span class="step active">01 · Describe</span><span class="step">02 · Review</span></div><p>Start with your acquisition thesis. You’ll review the criteria and operating authority before anything runs.</p><div class="field" style="margin-top:22px"><label for="new-brief">Your mandate</label><textarea class="welcome-input" id="new-brief" placeholder="Industry, geography, earnings, and what matters to you…">${esc(state.description)}</textarea></div><div class="field"><label for="new-name">Mandate name</label><input id="new-name" value="New Queensland mandate"></div><div class="drawer-actions">${btn('Review brief '+icon('arrow'),'data-action="wizard-next"','primary')}</div>`);else drawer('Review your mandate','New mandate · 2 of 2',`<div class="progress-track"><span class="step active">01 · Describe</span><span class="step active">02 · Review</span></div><h3>${esc(window.newMandate.name)}</h3><div class="brief-box" style="margin-top:17px">${esc(window.newMandate.description)}</div><div class="callout"><p>This prototype carries forward the example operating envelope: email only, anonymous introduction, $${state.budget} research limit, ${state.cap} new contacts per day.</p></div><p>No AI extraction runs in this mockup. Your brief is saved verbatim. Review and edit the operating plan before activation.</p><div class="drawer-actions">${btn('Back','data-action="wizard-back"')}${btn('Create draft mandate','data-action="wizard-create"','primary')}</div>`)}
function action(a){if(a==='pause'){state.paused=!state.paused;save();render();toast(state.paused?'Mandate paused. No new work will start.':'Mandate resumed in this demo.')}if(a==='reset'){state=structuredClone(initial);save();nav('overview');toast('Demo reset to its starting state.')}if(a==='new'){wizardStep=0;wizard()}if(a==='save-plan'){const name=$('#plan-name').value.trim(),budget=Number($('#plan-budget').value),cap=Number($('#plan-cap').value);if(!name||budget<126||budget>10000||cap<5||cap>50){toast('Enter a name, budget of $126–10,000 and 5–50 contacts.');return}state.name=name;state.description=$('#plan-description').value;state.budget=budget;state.cap=cap;save();render();toast('Operating plan saved to this browser.')}if(a==='completed')drawer('Completed meeting notes','Harbour Technical Services',`<span class="pill gray">13 Oct · Introductory call</span><h3>Outcome</h3><p>Owner is interested in a succession discussion over the next 12–18 months. No price expectations were discussed.</p><h3>Next steps</h3><p>Buyer to review business fit before requesting confidential information. Owner requested a follow-up in November.</p><div class="callout"><p>Illustrative notes only. This is not a real business or conversation.</p></div>`);if(a==='wizard-next'){let description=$('#new-brief').value.trim(),name=$('#new-name').value.trim();if(!description||!name){toast('Add a name and acquisition brief.');return}window.newMandate={name,description};wizardStep=1;wizard()}if(a==='wizard-back'){wizardStep=0;wizard()}if(a==='wizard-create'){state.name=window.newMandate.name;state.description=window.newMandate.description;state.paused=true;save();close();nav('plan');toast('Draft created and paused. Review the operating plan.')}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-exception]').forEach(b=>b.onclick=()=>openException(b.dataset.exception));document.querySelectorAll('[data-company]').forEach(b=>{b.onclick=()=>openCompany(b.dataset.company);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openCompany(b.dataset.company)}}});document.querySelectorAll('[data-meeting]').forEach(b=>b.onclick=()=>openMeeting(b.dataset.meeting));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const k=b.dataset.toggle;state[k]=!state[k];b.classList.toggle('on',state[k]);b.setAttribute('aria-checked',state[k]);save();toast('Demo authority updated. No live actions will run.')});if($('#target-search'))$('#target-search').oninput=e=>{query=e.target.value;$('#target-rows').innerHTML=targetRows();bindRows()}}
function bindRows(){document.querySelectorAll('#target-rows [data-company]').forEach(b=>{b.onclick=()=>openCompany(b.dataset.company);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openCompany(b.dataset.company)}}})}
function bindOverlay(){const o=$('#overlay');o.querySelector('[data-close]').onclick=close;o.querySelector('.backdrop').onclick=e=>{if(e.target.classList.contains('backdrop'))close()};o.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);o.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));o.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>openCompany(b.dataset.company));o.querySelectorAll('[data-meeting]').forEach(b=>b.onclick=()=>openMeeting(b.dataset.meeting));o.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>openConversation(b.dataset.conversation));o.querySelectorAll('[data-exception]').forEach(b=>b.onclick=()=>openException(b.dataset.exception));o.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>{if(!$('#exception-authority').checked){toast('Confirm the authority checkbox to continue.');return}if($('#reply-text')&&!$('#reply-text').value.trim()){toast('Add a response before approving.');return}if(!state.resolved.includes(b.dataset.resolve))state.resolved.push(b.dataset.resolve);activities.unshift(['Decision recorded',`${exceptions.find(e=>e.id===b.dataset.resolve).company}: approved in demo only.`,'Just now']);save();close();render();toast('Decision recorded. No message was sent.')});o.querySelectorAll('[data-exclude]').forEach(b=>b.onclick=()=>{let id=b.dataset.exclude;state.excluded=state.excluded.includes(id)?state.excluded.filter(x=>x!==id):[...state.excluded,id];save();close();render();toast(state.excluded.includes(id)?'Target excluded from this demo mandate.':'Target restored.')});o.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const c=companies.find(x=>x.id===b.dataset.copy);const t=`${c.name} — Meeting briefing\n${c.owner}\n${c.detail}\nEarnings and succession intentions remain unverified.\nAsk about owner plans, recurring customers and management independence.\nFictional prototype data.`;try{await navigator.clipboard.writeText(t);toast('Meeting briefing copied.')}catch{toast('Clipboard unavailable. Select and copy the briefing text.')}})}
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&$('.drawer')){const f=[...$('.drawer').querySelectorAll('button,input,textarea,select,[tabindex="0"]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});render();
